package lua

// TestGoldenCorpus & co. — the N3a standing regression gate
// (docs/Option-A-Plan.md §4): every corpus case runs through THIS
// interpreter and must reproduce its checked-in golden event log
// byte-for-byte. The goldens were generated by the carved artifact — the
// interpreter glasm gated byte-exact against stock C Lua 5.5.1 (official
// suite ≥95% + the required set green; docs/glasm-history/) — so any
// golden drift is a behavior change: an improvement lands as a deliberate
// golden update citing its ledger row, a regression fails the gate.
//
// Regenerate deliberately:   GOLDEN_UPDATE=1 go test . -run TestGolden
// (then `git diff _goldens/` — every changed line is a behavior delta).
//
// Pinned errors are not automatically divergences: the official suite
// ships blocks stock C Lua 5.5.1 itself fails under the user-tests
// posture (e.g. coroutine.lua:184's close-while-closing assert) — glasm's
// U5 gate proved the interp byte-exact with stock INCLUDING that failure,
// so the golden pins stock-faithful behavior. The _GOPHER_LUA_VERSION
// global is normalized to "<version>" in GLOBALS lines so version bumps
// don't churn the corpus.
//
// Ledger discipline carries over: every skip carries its reason, and the
// official-suite skips below are glasm's rulings verbatim (row numbers
// cite glasm's divergence ledger, docs/glasm-history/).

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const goldenDir = "_goldens"

var goldenSkipsOfficial = map[string]string{
	"main.lua":    "suite driver: spawns the lua binary as subprocesses (RUN/auxrun); the gate runs each test file directly instead",
	"all.lua":     "suite driver: dofiles main.lua and every file in sequence (subprocess driver) — see main.lua skip",
	"heavy.lua":   "stress script excluded from the official all.lua run; creates multi-hundred-MB strings (machine-dependent, not gate material)",
	"files.lua":   "the /dev/full block (files.lua:474-482) asserts io.flush FAILS with ENOSPC — macOS has no /dev/full, so the block cannot be expressed; everything through line 470 was green under the glasm gates. Revisit only with an ENOSPC-capable stand-in.",
	"closure.lua": "glasm row 79: no automatic GC cycles — closure.lua:39's repeat-until-GC waits for an unsolicited collection the fork never runs (weak tables DO clear on collectgarbage('collect'), gc.go; hangs, not fails)",
	"gc.lua":      "glasm row 79 (U5f): the full-collection weak walk (gc.go) is in, but fine-grained cycle semantics diverge (:316 finalizer reachability, :340 register residue)",
	"gengc.lua":   "glasm row 79 (U5c): generational-GC surface — gengc.lua:122 needs a minor collection to clear a __mode=\"kv\" table's entries",
	"cstack.lua":  "glasm row 78e (U5c closeout): xpcall(loop, loop) at cstack.lua:29 — the handler itself overflows and the fork's frame-reserve dialect re-raises 'C stack overflow' where stock says 'error in error handling'",
}

type goldenSpec struct {
	corpus     string // corpus dir (leading underscore)
	suiteFlags bool   // the official suite's _port/_soft/_nomsg posture
	skips      map[string]string
}

// TestGoldenOfficialSuite: _lua5.5-tests, the official 5.5.1 suite (heavy
// leg — skipped in -short mode, mirroring the glasm gate posture).
func TestGoldenOfficialSuite(t *testing.T) {
	if testing.Short() {
		t.Skip("official-suite leg — skipped in -short mode")
	}
	runGoldenCorpus(t, goldenSpec{corpus: "_lua5.5-tests", suiteFlags: true, skips: goldenSkipsOfficial})
}

// TestGoldenGlua: _glua-tests, the fork's own conformance suite.
func TestGoldenGlua(t *testing.T) {
	runGoldenCorpus(t, goldenSpec{corpus: "_glua-tests"})
}

// TestGoldenU1: _u1, the 5.2-core cases of the upgrade program.
func TestGoldenU1(t *testing.T) {
	runGoldenCorpus(t, goldenSpec{corpus: "_u1"})
}

func runGoldenCorpus(t *testing.T, spec goldenSpec) {
	cases, err := loadGoldenCorpus(spec.corpus)
	if err != nil {
		t.Fatal(err)
	}
	kept, skipped := filterGoldenSkips(cases, spec.skips)
	for _, s := range skipped {
		t.Logf("skip %s", s)
	}
	if len(kept) == 0 {
		t.Fatal("no cases loaded")
	}
	update := os.Getenv("GOLDEN_UPDATE") != ""
	sub := strings.TrimPrefix(spec.corpus, "_")
	seen := map[string]bool{}
	for _, c := range kept {
		name := c.Name
		seen[name+".golden"] = true
		got := strings.Join(goldenRun(c, spec.suiteFlags), "\n") + "\n"
		path := filepath.Join(goldenDir, sub, name+".golden")
		// Cases chdir; no parallel subtests.
		t.Run(sub+"/"+name, func(t *testing.T) {
			want, err := os.ReadFile(path)
			if update {
				if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
					t.Fatal(err)
				}
				if err := os.WriteFile(path, []byte(got), 0o644); err != nil {
					t.Fatal(err)
				}
				return
			}
			if err != nil {
				t.Fatalf("no golden for %s (generate with GOLDEN_UPDATE=1): %v", name, err)
			}
			if string(want) != got {
				t.Fatalf("golden drift (the interpreter's behavior changed; every diff line is a behavior delta — a deliberate update cites its ledger row):\n%s", goldenFirstDiff(string(want), got))
			}
		})
	}
	if update {
		// stale-golden sweep: nothing may linger after a deliberate update
		extras, err := staleGoldens(filepath.Join(goldenDir, sub), seen)
		if err != nil {
			t.Fatal(err)
		}
		for _, e := range extras {
			t.Errorf("stale golden (no corpus case): %s", e)
		}
	}
}

// filterGoldenSkips: every skip must carry a reason (ledger discipline —
// an empty reason is a bug).
func filterGoldenSkips(cases []goldenCase, skips map[string]string) ([]goldenCase, []string) {
	var kept []goldenCase
	var skipped []string
	for _, c := range cases {
		why, ok := skips[c.Name]
		if !ok {
			kept = append(kept, c)
			continue
		}
		if why == "" {
			panic("golden gate: skip without reason: " + c.Name)
		}
		skipped = append(skipped, fmt.Sprintf("%s (%s)", c.Name, why))
	}
	return kept, skipped
}

// goldenFirstDiff renders the first differing region of two event logs.
func goldenFirstDiff(want, got string) string {
	wl := strings.Split(want, "\n")
	gl := strings.Split(got, "\n")
	n := len(wl)
	if len(gl) > n {
		n = len(gl)
	}
	for i := 0; i < n; i++ {
		var w, g string
		if i < len(wl) {
			w = wl[i]
		}
		if i < len(gl) {
			g = gl[i]
		}
		if w != g {
			lo := i - 2
			if lo < 0 {
				lo = 0
			}
			hi := i + 3
			var b strings.Builder
			fmt.Fprintf(&b, "line %d:\n", i+1)
			for j := lo; j < hi; j++ {
				marker := " "
				if j == i {
					marker = ">"
				}
				if j < len(wl) {
					fmt.Fprintf(&b, "%s want | %s\n", marker, wl[j])
				}
				if j < len(gl) {
					fmt.Fprintf(&b, "%s got  | %s\n", marker, gl[j])
				}
			}
			return b.String()
		}
	}
	return "logs differ only in trailing bytes"
}

// staleGoldens lists golden files with no matching corpus case.
func staleGoldens(dir string, seen map[string]bool) ([]string, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	var extras []string
	for _, e := range entries {
		if !seen[e.Name()] {
			extras = append(extras, filepath.Join(dir, e.Name()))
		}
	}
	return extras, nil
}
